import{c as n,Q as t,j as r,g as l}from"./chunks/framework.hhGiamYR.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{"date":"2026-07-05T00:00:00.000Z","source":"discourses/book1/12-第十二章.md"},"headers":[],"relativePath":"fragments/2026-07-05.md","filePath":"fragments/2026-07-05.md"}'),a={name:"fragments/2026-07-05.md"};function s(o,e,u,p,c,d){return t(),r("div",null,[...e[0]||(e[0]=[l("p",null,'今天读到罗马士兵在维爱城的朱诺神庙里问神像"您要来罗马吗"，然后真的听到她说"是"。李维说他们那时笃信神明，进入神庙时秩序井然，虔诚肃穆。我停了下来。那一瞬间我嫉妒他们。不是我想要他们的迷信——是我想要他们那种相信一件事的能力。我活了五十八年，已经失去了相信任何东西的能力，除了"事实"。事实把我从牢房里救了出来吗？没有。事实没有让我回到国务厅。事实只是让我看清了一切——然后什么也做不了。罗马人相信神像会点头，所以他们赢了。我相信教皇是个骗子、教廷是意大利的毒瘤——然后我在圣安德烈亚养鸡。相信的人赢了，看清的人被流放。这就是我的发现。我不知道拿它怎么办。',-1),l("hr",null,null,-1),l("p",null,"我把教廷比作一个病人——病得太重不会痊愈，又没重到会死。它不够强，征服不了意大利；又不够弱，没法允许别人来征服。所以它让我们所有人悬在半空：不是活着，不是死了，就是一直悬着。查理曼是被它叫来的。法国人是被它叫来的。瑞士人也是被它叫来的。每一次都是教廷开的大门。不是外国人的错——他们只是从开着的门走进来。关上门的人是我们自己，因为我们没有一个能把门关上的君主。而那个本该关门的——教廷——把钥匙卖给了每一个路过的蛮族。……我在写这句话的时候心想，如果美第奇读到了，他会怎么想？他不会读的。上一个没读，这一个也不会。所以我为什么要写？因为我做不到不写。",-1),l("hr",null,null,-1),l("p",null,'"精明的人强化这种信仰，无论它有何起源。"我写下这句话的时候没有犹豫，但现在重读，我感到了那一刻我对自己做了一件什么事。我不是在描述别人的行为。我在推荐它。我在说：如果一个统治者知道神谕是伪造的，他应该把它说得更神圣。因为效果比真相更重要。这是《君主论》的延续——但我读这一章的时候比写《君主论》的时候更不安。在《君主论》里我是写给一个人看的，我可以说"这是给您的话"。在这里我是写给我自己看的。没有观众。这意味着我真的相信。我真相信谎言比真相有用。……也许这就是为什么没人想让我回来。不是因为我说了太多真相。是因为我说谎说得太真诚了。',-1),l("hr",null,null,-1),l("p",null,"最后的那个实验——把罗马教廷送到瑞士去——写完以后我在椅子上坐了很久。那些瑞士人，唯一还恪守先祖之道的民族，用不了多久就会被教廷的恶习腐蚀。我不是在诅咒教廷。我是在描述一个规律：腐败是会传染的，而传染源从来不是底层的人。传染源总是来自上面。最神圣的地方就是最腐败的地方。这不是悖论。这是我在国务厅十四年里每天看到的东西。我从来没有对韦托里说过这句话。他也许知道，但说出来不一样。有些话是对古人说的，有些话是对朋友说的，有些话只能对自己说。这一句我留给了自己。但现在我写下来了。也许有一天有人会读到。那时候我已经不在了。那也好。",-1),l("hr",null,null,-1),l("p",null,'不对。让我重新想。我刚才说的是"看清的人被流放，相信的人赢了"。但罗马人不是相信者——他们是被治理者。说神像点头的人不是那个士兵，是卡米卢斯。卡米卢斯知道自己在做什么。他接受了士兵们以为看到的神迹，然后"予以发扬光大"。所以不是"相信的人赢了"——是"让下属相信的人赢了"。罗马士兵相信神像在对他们说话，所以他们纪律严明，秩序井然，赢得战争。他们的相信是卡米卢斯手里的工具。……这更糟了。这说明我的处境不是"我不够天真"，而是"我没有成为卡米卢斯"。我没有让任何人相信我。我没有让美第奇相信我，没有让共和国相信我，甚至韦托里也只是把我当成一个有趣的朋友。我不是那个让神像点头的人。我是一个站在神像前等着它点头的人——而且我知道它是石头做的。',-1)])])}const i=n(a,[["render",s]]);export{f as __pageData,i as default};
